use argon2::{Argon2, PasswordHash, PasswordHasher, PasswordVerifier};
use password_hash::{rand_core::OsRng, SaltString};
use rand::{distributions::Alphanumeric, Rng};
use serde::{Deserialize, Serialize};
use std::{
    fs,
    path::PathBuf,
    sync::{Arc, RwLock},
    time::{SystemTime, UNIX_EPOCH},
};

fn now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
fn id(prefix: &str) -> String {
    format!(
        "{}_{}",
        prefix,
        rand::thread_rng()
            .sample_iter(&Alphanumeric)
            .take(18)
            .map(char::from)
            .collect::<String>()
    )
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum IdentityStatus {
    Unverified,
    Active,
    Suspended,
    Locked,
    Revoked,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Identity {
    pub identity_id: String,
    pub subject_id: String,
    pub provider: String,
    pub provider_subject: String,
    pub email: Option<String>,
    pub display_name: Option<String>,
    pub status: IdentityStatus,
    pub created_at: u64,
    pub metadata: serde_json::Value,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IdentitySession {
    pub session_id: String,
    pub identity_id: String,
    pub subject_id: String,
    pub issued_at: u64,
    pub expires_at: u64,
    pub last_seen_at: u64,
    pub device: Option<String>,
    pub provider: String,
    pub status: String,
    pub revocation_reason: Option<String>,
    pub refresh_hash: Option<String>,
}
#[derive(Debug, Default, Serialize, Deserialize)]
struct State {
    identities: Vec<Identity>,
    sessions: Vec<IdentitySession>,
    password_hashes: std::collections::HashMap<String, String>,
}
#[derive(Clone)]
pub struct IdentityStore {
    path: PathBuf,
    state: Arc<RwLock<State>>,
}

impl IdentityStore {
    pub fn load(path: impl Into<PathBuf>) -> Result<Self, String> {
        let path = path.into();
        let state = if path.exists() {
            serde_json::from_slice(&fs::read(&path).map_err(|e| e.to_string())?)
                .map_err(|e| e.to_string())?
        } else {
            State::default()
        };
        Ok(Self {
            path,
            state: Arc::new(RwLock::new(state)),
        })
    }
    fn persist(&self, s: &State) -> Result<(), String> {
        if let Some(p) = self.path.parent() {
            fs::create_dir_all(p).map_err(|e| e.to_string())?
        }
        fs::write(
            &self.path,
            serde_json::to_vec_pretty(s).map_err(|e| e.to_string())?,
        )
        .map_err(|e| e.to_string())
    }
    pub fn normalize(
        &self,
        provider: &str,
        provider_subject: &str,
        email: Option<String>,
        display_name: Option<String>,
        metadata: serde_json::Value,
    ) -> Result<Identity, String> {
        let mut s = self.state.write().map_err(|_| "identity lock poisoned")?;
        if let Some(i) = s
            .identities
            .iter()
            .find(|i| i.provider == provider && i.provider_subject == provider_subject)
        {
            return Ok(i.clone());
        }
        let x = Identity {
            identity_id: id("identity"),
            subject_id: id("subject"),
            provider: provider.into(),
            provider_subject: provider_subject.into(),
            email,
            display_name,
            status: IdentityStatus::Unverified,
            created_at: now(),
            metadata,
        };
        s.identities.push(x.clone());
        self.persist(&s)?;
        Ok(x)
    }
    pub fn list(&self) -> Result<Vec<Identity>, String> {
        Ok(self
            .state
            .read()
            .map_err(|_| "identity lock poisoned")?
            .identities
            .clone())
    }
    pub fn sign_up(
        &self,
        email: &str,
        password: &str,
        display_name: Option<String>,
    ) -> Result<(Identity, IdentitySession, String), String> {
        let normalized = email.trim().to_lowercase();
        if normalized.is_empty() || password.len() < 8 {
            return Err("email and a password of at least 8 characters are required".into());
        }
        if self
            .state
            .read()
            .map_err(|_| "identity lock poisoned")?
            .identities
            .iter()
            .any(|value| value.email.as_deref() == Some(&normalized))
        {
            return Err("identity already exists".into());
        }
        let mut identity = self.normalize(
            "password",
            &normalized,
            Some(normalized.clone()),
            display_name,
            serde_json::json!({}),
        )?;
        identity.status = IdentityStatus::Active;
        let mut state = self.state.write().map_err(|_| "identity lock poisoned")?;
        if let Some(stored) = state
            .identities
            .iter_mut()
            .find(|value| value.identity_id == identity.identity_id)
        {
            stored.status = IdentityStatus::Active;
        }
        state
            .password_hashes
            .insert(identity.subject_id.clone(), Self::hash_password(password)?);
        self.persist(&state)?;
        drop(state);
        let (session, token) = self.issue_session(&identity, "password", None, 15 * 60)?;
        Ok((identity, session, token))
    }
    pub fn sign_in(
        &self,
        email: &str,
        password: &str,
    ) -> Result<(Identity, IdentitySession, String), String> {
        let normalized = email.trim().to_lowercase();
        let state = self.state.read().map_err(|_| "identity lock poisoned")?;
        let identity = state
            .identities
            .iter()
            .find(|value| {
                value.email.as_deref() == Some(&normalized)
                    && value.status == IdentityStatus::Active
            })
            .cloned()
            .ok_or("invalid credentials")?;
        let valid = state
            .password_hashes
            .get(&identity.subject_id)
            .is_some_and(|hash| Self::verify_password(hash, password));
        drop(state);
        if !valid {
            return Err("invalid credentials".into());
        }
        let (session, token) = self.issue_session(&identity, "password", None, 15 * 60)?;
        Ok((identity, session, token))
    }
    pub fn authenticate_session(&self, token: &str) -> Option<IdentitySession> {
        let current = now();
        self.state
            .read()
            .ok()?
            .sessions
            .iter()
            .find(|value| {
                value
                    .refresh_hash
                    .as_deref()
                    .is_some_and(|hash| Self::verify_password(hash, token))
                    && value.status == "active"
                    && value.expires_at > current
            })
            .cloned()
    }
    pub fn sessions(&self, subject: &str) -> Result<Vec<IdentitySession>, String> {
        Ok(self
            .state
            .read()
            .map_err(|_| "identity lock poisoned")?
            .sessions
            .iter()
            .filter(|x| x.subject_id == subject)
            .cloned()
            .collect())
    }
    pub fn issue_session(
        &self,
        identity: &Identity,
        provider: &str,
        device: Option<String>,
        ttl: u64,
    ) -> Result<(IdentitySession, String), String> {
        let mut s = self.state.write().map_err(|_| "identity lock poisoned")?;
        let t = now();
        let token = id("session_token");
        let x = IdentitySession {
            session_id: id("session"),
            identity_id: identity.identity_id.clone(),
            subject_id: identity.subject_id.clone(),
            issued_at: t,
            expires_at: t + ttl,
            last_seen_at: t,
            device,
            provider: provider.into(),
            status: "active".into(),
            revocation_reason: None,
            refresh_hash: Some(Self::hash_password(&token)?),
        };
        s.sessions.push(x.clone());
        self.persist(&s)?;
        Ok((x, token))
    }
    pub fn revoke_session(&self, subject: &str, session: &str, reason: &str) -> Result<(), String> {
        let mut s = self.state.write().map_err(|_| "identity lock poisoned")?;
        let x = s
            .sessions
            .iter_mut()
            .find(|x| x.subject_id == subject && x.session_id == session)
            .ok_or("session not found")?;
        x.status = "revoked".into();
        x.revocation_reason = Some(reason.into());
        self.persist(&s)
    }
    pub fn revoke_all(&self, subject: &str) -> Result<usize, String> {
        let mut s = self.state.write().map_err(|_| "identity lock poisoned")?;
        let mut n = 0;
        for x in s
            .sessions
            .iter_mut()
            .filter(|x| x.subject_id == subject && x.status == "active")
        {
            x.status = "revoked".into();
            x.revocation_reason = Some("logout_all".into());
            n += 1
        }
        self.persist(&s)?;
        Ok(n)
    }
    pub fn hash_password(password: &str) -> Result<String, String> {
        let salt = SaltString::generate(&mut OsRng);
        Argon2::default()
            .hash_password(password.as_bytes(), &salt)
            .map(|x| x.to_string())
            .map_err(|e| e.to_string())
    }
    pub fn verify_password(hash: &str, password: &str) -> bool {
        PasswordHash::new(hash)
            .map(|x| {
                Argon2::default()
                    .verify_password(password.as_bytes(), &x)
                    .is_ok()
            })
            .unwrap_or(false)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn provider_identity_is_normalized_and_persisted() {
        let p = std::env::temp_dir().join(format!("identity-{}.json", now()));
        let s = IdentityStore::load(&p).unwrap();
        let a = s
            .normalize(
                "github",
                "42",
                Some("a@example.com".into()),
                None,
                serde_json::json!({}),
            )
            .unwrap();
        let b = s
            .normalize("github", "42", None, None, serde_json::json!({}))
            .unwrap();
        assert_eq!(a.identity_id, b.identity_id);
        assert_eq!(s.list().unwrap().len(), 1);
    }
    #[test]
    fn password_hash_never_equals_password() {
        let h = IdentityStore::hash_password("correct horse").unwrap();
        assert_ne!(h, "correct horse");
        assert!(IdentityStore::verify_password(&h, "correct horse"));
        assert!(!IdentityStore::verify_password(&h, "wrong"));
    }
    #[test]
    fn actor_tokens_are_short_lived_hashed_and_revocable() {
        let p = std::env::temp_dir().join(format!("identity-session-{}.json", id("test")));
        let store = IdentityStore::load(&p).unwrap();
        let (identity, session, token) = store
            .sign_up("actor@example.com", "correct horse", Some("Actor".into()))
            .unwrap();
        assert!(session.expires_at - session.issued_at <= 15 * 60);
        assert_ne!(session.refresh_hash.as_deref(), Some(token.as_str()));
        assert_eq!(
            store.authenticate_session(&token).unwrap().subject_id,
            identity.subject_id
        );
        store
            .revoke_session(&identity.subject_id, &session.session_id, "test")
            .unwrap();
        assert!(store.authenticate_session(&token).is_none());
        let _ = std::fs::remove_file(p);
    }
}
